import {environmentMessage as message} from './messages.mjs';
import {workbenchMessage as workbench} from './workbench-messages.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>message(k,I18n.language),w=k=>workbench(k,I18n.language),num=(n,d=3)=>Number.isFinite(n)?new Intl.NumberFormat(I18n.locale,{maximumFractionDigits:d}).format(n):t('missing');
const label=k=>k.startsWith('current_')?w(k):t(k),warning=k=>workbench(k,I18n.language)!==k?w(k):t(k);
export class EnvironmentalInspector{
  constructor(container,service,{onPoint=()=>{},shouldHandleMapClick=()=>true}={}){this.container=container;this.service=service;this.onPoint=onPoint;this.shouldHandleMapClick=shouldHandleMapClick;this.context=null;this.result=null;this.generation=0;this.inputs={latitude:'',longitude:'',date:'',temporalMode:'exact',includeSeaIce:false,bearing:''};this.map=null;this.marker=null;container.dataset.userContent='';container.addEventListener('submit',e=>{e.preventDefault();this.query();});container.addEventListener('input',()=>{this.readInputs();this.result=null;++this.generation;this.clearMarker();container.querySelector('[data-environment-result]')?.replaceChildren();});container.addEventListener('change',()=>this.readInputs());}
  clearMarker(){if(this.marker&&this.map)this.map.removeLayer(this.marker);this.marker=null;}
  readInputs(){const f=this.container.querySelector('form');if(f)this.inputs={latitude:f.elements.latitude.value,longitude:f.elements.longitude.value,date:f.elements.date.value,temporalMode:f.elements.temporalMode.value,includeSeaIce:f.elements.includeSeaIce?.checked||false,bearing:f.elements.bearing?.value||''};}
  clear(){this.readInputs();++this.generation;this.context=null;this.result=null;this.container.replaceChildren();this.clearMarker();}
  update({dataset,variable,timeSlice,map}){this.readInputs();const changed=!this.context||this.context.dataset.id!==dataset.id||this.context.timeSlice.id!==timeSlice.id||this.context.variable!==variable;if(changed){this.inputs.date=timeSlice.time.slice(0,10);this.result=null;++this.generation;this.clearMarker();}if(!this.context||this.context.dataset.manifest.kind!==dataset.manifest.kind)this.inputs.temporalMode='exact';this.context={dataset,variable,timeSlice};if(this.map!==map){this.map=map;map.on('click',e=>{if(!this.context||!this.shouldHandleMapClick())return;this.inputs.latitude=e.latlng.lat.toFixed(5);this.inputs.longitude=e.latlng.lng.toFixed(5);this.onPoint();this.render();this.query();});}this.render();}
  render(){
    if(!this.context)return;const {dataset,variable,timeSlice:s}=this.context,m=dataset.manifest,scale=m.scales[variable],currents=m.kind==='currents',isMask=variable==='mask',mode=currents?'calendar-month':'interval-mean',note=currents?w('currentResolution'):t('resolution'),period=currents?w('monthly'):t('period');
    this.container.innerHTML=`<div class="environment-layer-details"><div class="environment-legend"><strong>${esc(label(variable))}${scale.units?' · '+esc(scale.units):''}</strong>${isMask?`<small>${esc(t('maskLegend'))}</small>`:`<div class="environment-colorbar ${currents?(variable==='current_speed'?'current':'divergent'):variable==='sea_ice_fraction'?'ice':variable==='sst_uncertainty'?'uncertainty':''}"></div><div class="environment-scale"><span>${num(scale.min)}</span><span>${num(scale.max)}</span></div>`}<p>${esc(note)}</p>${currents?'':`<p>${esc(t('nativeCoverage'))}</p>`}</div><div class="environment-period"><strong>${esc(period)} · ${s.id.slice(0,4)}-${s.id.slice(4)}</strong>${currents?`<small>${esc(w('currentTemporal'))}</small>`:`<span>${esc(s.start)}<br>→ ${esc(s.end)}</span>`}<small>${esc(t('representative'))}<br>${esc(s.time)}</small></div><details class="environment-notes"><summary>${esc(w('details'))}</summary>${(currents?[w('currentQuality'),w('historical'),w('vectorMeaning')]:[t('timeWarning'),t('sourceNature'),t('maskNote'),t('iceNote'),t('uncertaintyNote'),t('noBiology')]).map(n=>`<p>${esc(n)}</p>`).join('')}<a href="data/environment/${currents?'CURRENTS_OBSERVATIONS_INTEGRATION':'SST_2025_INTEGRATION'}.md" target="_blank" rel="noopener">${esc(w('sourceAudit'))} ↗</a></details></div><form class="environment-query"><h3>${esc(currents?w('point'):t('query'))}</h3><p>${esc(t('clickMap'))}</p><div class="environment-coordinate-fields"><label>${esc(t('latitude'))}<input type="number" name="latitude" step="any" min="-90" max="90" required value="${esc(this.inputs.latitude)}"></label><label>${esc(t('longitude'))}<input type="number" name="longitude" step="any" min="-180" max="180" required value="${esc(this.inputs.longitude)}"></label></div><label>${esc(t('date'))}<input type="date" name="date" required value="${esc(this.inputs.date)}"></label><label>${esc(t('timeMode'))}<select name="temporalMode"><option value="exact" ${this.inputs.temporalMode==='exact'?'selected':''}>${esc(t('exact'))}</option><option value="${mode}" ${this.inputs.temporalMode===mode?'selected':''}>${esc(currents?w('calendarMode'):t('interval'))}</option></select></label>${currents?`<details class="environment-projection"><summary>${esc(w('routeProjection'))}</summary><label>${esc(w('bearing'))}<input type="number" name="bearing" min="0" max="359.999" step="any" value="${esc(this.inputs.bearing)}"></label><p>${esc(w('projectionNote'))}</p></details>`:`<label class="environment-checkbox"><input type="checkbox" name="includeSeaIce" ${this.inputs.includeSeaIce?'checked':''}><span>${esc(t('includeIce'))}</span></label>`}<button type="submit" class="btn primary full">${esc(t('run'))}</button></form><div data-environment-result class="environment-point-result" role="status">${this.result?this.resultHTML(this.result):''}</div>`;
  }
  resultHTML(r){
    if(r.status==='loading')return `<p>${esc(t('loading'))}</p>`;const currents=this.context?.dataset.manifest.kind==='currents';
    const rows=[[t('value'),r.value==null?t('missing'):num(r.value)+' '+r.units],...(r.kelvin==null?[]:[['Kelvin',num(r.kelvin)+' K']]),...(currents&&r.vector?[[w('current_u'),num(r.vector.u)+' m/s'],[w('current_v'),num(r.vector.v)+' m/s'],[w('current_direction'),r.vector.direction==null?'—':num(r.vector.direction,1)+'°'],...(r.vector.alongTrack==null?[]:[[w('routeProjection'),num(r.vector.alongTrack)+' m/s']])]:[]),[currents?w('uncertainty'):t('uncertainty'),r.uncertainty?.value==null?(currents?w('notProvided'):t('missing')):num(r.uncertainty.value)+' K'],[t('representative'),r.time||'—'],[t('bounds'),currents?w('noBounds'):r.sourceInterval?r.sourceInterval.start+' → '+r.sourceInterval.end:'—'],[t('cell'),r.gridCell?num(r.gridCell.latitude,5)+' / '+num(r.gridCell.longitude,5):'—'],...(currents?[[w('depth'),num(r.depthMeters,6)+' m']]:[[t('surface'),r.quality?t(r.quality.surfaceType)+' · '+num(r.quality.sourceMask,0):'—'],[t('sea_ice_fraction'),r.quality?.seaIceFraction==null?'—':num(r.quality.seaIceFraction,4)]])];
    return `${r.status==='available'?'':`<p class="environment-query-warning">${esc(warning(r.reason||r.status))}</p>`}<dl>${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><details class="environment-result-source"><summary>${esc(w('details'))}</summary><dl><div><dt>${esc(t('source'))}</dt><dd>${esc(r.source?.originalFile||'—')}</dd></div><div><dt>SHA-256</dt><dd>${esc(r.source?.sha256||'—')}</dd></div><div><dt>${esc(t('source'))} · licence</dt><dd>${esc(r.source?.license||'—')}</dd></div></dl><p>${esc(currents?w('currentQuality'):t('uncertaintyNote'))}</p></details>${r.quality?.upstreamIceEstimate?`<p>${esc(t('iceNote'))}</p>`:''}<p class="small-note">${esc(currents?w('historical'):t('noBiology'))}</p>`;
  }
  async query(){if(!this.context)return;this.readInputs();const {dataset,variable}=this.context,latitude=this.inputs.latitude===''?NaN:Number(this.inputs.latitude),longitude=this.inputs.longitude===''?NaN:Number(this.inputs.longitude),generation=++this.generation;this.clearMarker();this.result={status:'loading'};this.render();const result=await this.service.getEnvironmentalValue(variable,latitude,longitude,this.inputs.date,{datasetId:dataset.id,temporalMode:this.inputs.temporalMode,includeSeaIce:this.inputs.includeSeaIce,bearingDegrees:this.inputs.bearing===''?undefined:Number(this.inputs.bearing)});if(generation!==this.generation)return;this.result=result;this.render();this.container.querySelector('[data-environment-result]')?.scrollIntoView({block:'nearest',behavior:'instant'});this.clearMarker();if(result.gridCell&&Number.isFinite(result.gridCell.latitude)&&result.status==='available'){this.marker=window.L.circleMarker([result.gridCell.latitude,result.gridCell.longitude],{radius:6,color:'#fff',weight:2,fillColor:'#102f41',fillOpacity:1}).addTo(this.map);const text=document.createElement('span');text.textContent=label(variable)+': '+num(result.value)+' '+result.units;this.marker.bindTooltip(text).openTooltip();}}
}
